{"check_build": {"code": "script({
  title: 'Buddhist temple precinct: shoji hall, five-storey pagoda and bell tower',
  palette: { stone: { mix: ['light bluish grey', 'dark bluish grey'] }, plaster: 'white', lacquer: 'dark red', timber: 'reddish brown', roof: { mix: ['dark bluish grey', 'black'] }, trim: 'dark brown', gold: 'pearl gold' }
});

section('Podium', [
  box({ at: [4, 0, 12], size: [64, '2b', 32], colour: 'stone', texture: 'masonry', top: 'tile' }),
  stairs({ at: [19, 0, 6], width: 6, steps: 6, dir: '+z', colour: 'stone' })
]);

const hallOpenings = [
  { side: 'front', at: 14, width: 4, height: 18, door: 'lacquer', opens: 'out' },
  { side: 'front', at: 4, width: 4, y: 6, height: 9, frame: 'trim' },
  { side: 'front', at: 24, width: 4, y: 6, height: 9, frame: 'trim' },
  { side: 'left', at: 9, width: 4, y: 6, height: 9, frame: 'trim' },
  { side: 'right', at: 9, width: 4, y: 6, height: 9, frame: 'trim' },
  { side: 'back', at: 4, width: 4, y: 6, height: 9, frame: 'trim' },
  { side: 'back', at: 24, width: 4, y: 6, height: 9, frame: 'trim' }
];

section('Hall', [
  room({ at: [6, 6, 14], size: [32, '6b', 22], colour: 'plaster', texture: 'grille', floor: 'timber', openings: hallOpenings }),
  roof({ style: 'hip', at: [6, 24, 14], size: [32, 22], colour: 'roof' }),
  ...[8, 16, 28, 36].map((x) => column({ at: [x, 6, 13], height: 18, diameter: 1, colour: 'lacquer' }))
]);

const CX = 54, CZ = 30, TIERS = [20, 16, 12, 8, 6], BODY = 9;
const pagoda = [];
let yb = 6;
TIERS.forEach((s, k) => {
  const next = TIERS[k + 1];
  const x0 = CX - s / 2, z0 = CZ - s / 2;
  pagoda.push(
    box({ at: [x0, yb, z0], size: [s, BODY, s], colour: 'lacquer', texture: 'log' }),
    floor({ at: [x0, yb + BODY, z0], size: [s, s], colour: 'plaster', layers: 1 }),
    roof({ style: 'hip', at: [x0, yb + BODY + 1, z0], size: [s, s], colour: 'roof', holes: next ? [{ at: [CX - next / 2, CZ - next / 2], size: [next, next] }] : null })
  );
  yb += BODY + 1;
});
section('Pagoda', pagoda);

section('Bell tower', [
  ...[[50, 12], [55, 12], [50, 17], [55, 17]].map(([x, z]) => column({ at: [x, 6, z], height: 9, diameter: 1, colour: 'trim' })),
  floor({ at: [51, 6, 13], size: [4, 4], colour: 'stone', layers: 1 }),
  cylinder({ at: [51, 7, 13], diameter: 4, height: 6, colour: 'gold' }),
  roof({ style: 'hip', at: [50, 15, 12], size: [6, 6], colour: 'roof' })
]);

const lantern = (x, z) => [
  box({ at: [x, 0, z], size: [3, '1b', 3], colour: 'stone' }),
  column({ at: [x + 1, 3, z + 1], height: 6, diameter: 1, colour: 'stone' }),
  box({ at: [x, 9, z], size: [3, '1b', 3], colour: 'stone' }),
  place({ part: '4589', at: [x + 1, 12, z + 1], colour: 'dark bluish grey' })
];

section('Grounds', [
  lantern(11, 6),
  lantern(31, 6),
  place({ part: '3471', at: [0, 0, 2], colour: 'green' }),
  place({ part: '2435', at: [0, 0, 28], colour: 'dark green' }),
  place({ part: '3471', at: [70, 0, 8], colour: 'green' }),
  place({ part: '3471', at: [70, 0, 24], colour: 'green' }),
  place({ part: '2435', at: [70, 0, 40], colour: 'dark green' })
]);
","seed": 1}}

